const ctx = $input.item.json;

const filePath   = ctx.file_path   || 'unknown';
const language   = ctx.language    || 'unknown';
const description= ctx.description || '';
const today      = new Date().toISOString().split('T')[0];
const safeTitle  = (description || filePath)
  .replace(/[^a-zA-Z0-9_\-\.]/g, '_')
  .replace(/^_+|_+$/g, '')
  .substring(0, 60);

return [{
  json: {
    file_path:    filePath,
    language:     language,
    description:  description,
    today:        today,
    safe_title:   safeTitle,
    vault_path:   $env.VAULT_PATH  || '/vault',
    ollama_url:   $env.OLLAMA_URL  || 'http://ollama:11434',
    ollama_model: $env.OLLAMA_MODEL|| 'deepseek-r1:7b'
  }
}];

const prev    = $('Prepare Context').item.json;
const resp    = $input.item.json;
const content = resp.message?.content || resp.choices?.[0]?.message?.content || '';

const noteDir  = `${prev.vault_path}/research`;
const fileName = `${prev.today}_research_${prev.safe_title}.md`;
const fullPath = `${noteDir}/${fileName}`;

return [{
  json: {
    ...prev,
    note_content: content,
    note_dir:     noteDir,
    file_name:    fileName,
    full_path:    fullPath
  }
}];

const ctx = $('Build File Path').item.json;
return [{
  json: {
    agent:     'researcher',
    status:    'success',
    note_path: ctx.full_path,
    title:     ctx.safe_title,
    today:     ctx.today
  }
}];
